    onError: async (error) => {
      if (!(error instanceof HttpError && error.status === 409)) return;""", """      clear();
    },
    onError: async (error) => {
      if (!(error instanceof HttpError && error.status === 409)) {
        if (editing) {
          keepError.current = true;
          clear();
        }
        return;
      }""")
sub(p, """  const submit = useSubmitOnce(save);
