    setName('');
    setGrade('A');
    setGradeFrom('');
    setTerms('');
    setVersion(undefined);
    setEditing(undefined);
  };""")
sub(p, """  useEffect(() => {
    save.reset();""", """  useEffect(() => {
    if (keepError.current) keepError.current = false;
    else save.reset();""")
